  ui.arena = { el: arena, fid: F ? F.id : null, nodes: [], lastSeq: 0, lastLog: -1, over: false, theme: isDark(), view };
  arena.className = "arena " + (view === "compact" ? "cmpmode" : "v2"); arena.style.height = "";
