  if (ON && window.GUILD) setTimeout(() => window.GUILD.start(), 700);
  if (ON) { setTimeout(brisageNet, 5000); setInterval(brisageNet, 15000); }
  if (pushNow) setTimeout(() => onPush().then((r) => { if (r === "ok") toast("Partie envoyée sur ton compte."); }), 400);
